SELECT status_group, delivered_cost, max_cost FROM (SELECT CASE WHEN status IN ('RETURNED', 'LOST') THEN 'group_a' ELSE 'other' END AS status_group, SUM(CASE WHEN status = 'DELIVERED' THEN cost ELSE 0 END) AS delivered_cost, MAX(cost) AS max_cost FROM shipments GROUP BY CASE WHEN status IN ('RETURNED', 'LOST') THEN 'group_a' ELSE 'other' END) AS agg WHERE delivered_cost < 47 ORDER BY delivered_cost DESC
